@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource-variable/newsreader/opsz-italic.css";
@import "@fontsource/dm-mono/400.css";
@import "@fontsource/dm-mono/500.css";

/* Light (faithful): cream page (251,250,246), black-85% ink, black-42% quiet type, a pure-black
   CTA with off-white type (248,248,248), white label pills, black-8% fills and hairlines, gold
   (255,203,48) and butter (255,228,140) for the hero light. Charts use the site's accent set
   (red, blue, pink, amber, brown). */
:root {
  --background: oklch(0.985 0.006 95);
  --foreground: oklch(0.255 0.002 100);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.255 0.002 100);
  --popover: oklch(0.98 0 0);
  --popover-foreground: oklch(0.255 0.002 100);
  --primary: oklch(0 0 0);
  --primary-foreground: oklch(0.98 0 0);
  --secondary: oklch(0.925 0.004 95);
  --secondary-foreground: oklch(0.255 0.002 100);
  --muted: oklch(0.94 0.004 95);
  --muted-foreground: oklch(0.63 0.004 95);
  --accent: oklch(0.955 0.004 95);
  --accent-foreground: oklch(0.255 0.002 100);
  --destructive: oklch(0.645 0.225 33);
  --destructive-foreground: oklch(0.98 0 0);
  --border: oklch(0.915 0.004 95);
  --input: oklch(0.88 0.004 95);
  --ring: oklch(0.6 0.004 95);
  --highlight: oklch(0.872 0.168 86);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.925 0.112 92);
  --chart-1: oklch(0.645 0.225 33);
  --chart-2: oklch(0.555 0.235 262);
  --chart-3: oklch(0.68 0.3 330);
  --chart-4: oklch(0.82 0.17 75);
  --chart-5: oklch(0.24 0.07 35);
  --sidebar: oklch(0.97 0.004 95);
  --sidebar-foreground: oklch(0.255 0.002 100);
  --sidebar-primary: oklch(0 0 0);
  --sidebar-primary-foreground: oklch(0.98 0 0);
  --sidebar-accent: oklch(0.925 0.004 95);
  --sidebar-accent-foreground: oklch(0.255 0.002 100);
  --sidebar-border: oklch(0.915 0.004 95);
  --sidebar-ring: oklch(0.6 0.004 95);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Newsreader Variable", ui-serif, Georgia, serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  --radius: 0.75rem;
  --page-width: 73.75rem;
  --page-gutter: 0.625rem;
  --section-y: 5rem;
}

@media (min-width: 48rem) {
  :root {
    --page-gutter: 1.5rem;
    --section-y: 7.5rem;
  }
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 2rem;
  }
}

/* Dark: the same page at dusk. Warm charcoal ground, cream ink and cream pills with black
   type, white-10% hairlines, the hero gold deepened to amber, the butter pools kept pale. */
.dark {
  --background: oklch(0.17 0.006 80);
  --foreground: oklch(0.965 0.005 95);
  --card: oklch(0.215 0.006 80);
  --card-foreground: oklch(0.94 0.006 95);
  --popover: oklch(0.215 0.006 80);
  --popover-foreground: oklch(0.94 0.006 95);
  --primary: oklch(0.97 0.006 95);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.27 0.006 80);
  --secondary-foreground: oklch(0.94 0.006 95);
  --muted: oklch(0.245 0.006 80);
  --muted-foreground: oklch(0.68 0.006 90);
  --accent: oklch(0.26 0.006 80);
  --accent-foreground: oklch(0.94 0.006 95);
  --destructive: oklch(0.68 0.2 33);
  --destructive-foreground: oklch(0.98 0 0);
  --border: oklch(1 0 0 / 11%);
  --input: oklch(1 0 0 / 16%);
  --ring: oklch(0.6 0.006 90);
  --highlight: oklch(0.76 0.16 78);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.84 0.11 85);
  --chart-1: oklch(0.68 0.2 33);
  --chart-2: oklch(0.62 0.2 262);
  --chart-3: oklch(0.7 0.26 330);
  --chart-4: oklch(0.82 0.17 75);
  --chart-5: oklch(0.55 0.09 45);
  --sidebar: oklch(0.2 0.006 80);
  --sidebar-foreground: oklch(0.94 0.006 95);
  --sidebar-primary: oklch(0.97 0.006 95);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.27 0.006 80);
  --sidebar-accent-foreground: oklch(0.94 0.006 95);
  --sidebar-border: oklch(1 0 0 / 11%);
  --sidebar-ring: oklch(0.6 0.006 90);
}
